rame--{{ props.direction|default('left') }}" tabindex="0"{% if props.title is not empty %} role="region" aria-label="{{ props.title }}"{% endif %} data-cms-sizes="(min-width: 48rem) 24rem, 18rem"><ul class="carousel__track">{% for slide in props.slides %}<li class="carousel__slide">{% if slide.image %}<img class="carousel__image" src="{{ slide.image }}" alt="{{ slide.alt }}">{% endif %}{% if slide.caption is not empty %}<p class="carousel__caption">{{ slide.caption }}</p>{% endif %}</li>{% endfor %}{% for slide in props.slides %}<li class="carousel__slide carousel__slide--copy" aria-hidden="true">{% if slide.image %}<img class="carousel__image" src="{{ slide.image }}" alt="">{% endif %}{% if slide.caption is not empty %}<p class="carousel__caption">{{ slide.caption }}</p>{% endif %}</li>{% endfor %}</ul></div></section>","css":".carousel__title { margin: 0 0 1rem; color: var(--cms-color-text); }
